```php
class Facade
{

    private Subsystem $subsystemA;
    private Subsystem $subsystemB;

    public function __construct(Subsystem $subsystemA, Subsystem $subsystemB)
    {
        $this->subsystemA = $subsystemA;
        $this->subsystemB = $subsystemB;
